/* Scoped reset — Figma has no default margins */
.c-path, .c-path *, .c-path *::before, .c-path *::after { box-sizing: border-box; }
.c-path :where(h1, h2, h3, p, ul, li, figure) { margin: 0; padding: 0; }
.c-path :where(button) { border: 0; background: none; padding: 0; font: inherit; color: inherit; cursor: pointer; }
.c-path :where(a) { color: inherit; text-decoration: none; }
.c-path :where(img) { display: block; }

.c-path {
  display: flex;
  flex-direction: column;
  padding: 16px;
  gap: 8px;
  font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.c-path__text {
  color: #111827;
  font-size: 14px;
  font-weight: 400;
  line-height: 20px;
  white-space: nowrap;
}

.c-path__image {
  width: 40px;
  height: 40px;
}

